import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError { field: string; message: string }

class HttpError extends Error {
  constructor(public status: number, public code: string, message: string, public fields?: FieldError[]) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, extra: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...extra });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, e: HttpError): void {
  const error: Record<string, unknown> = { code: e.code, message: e.message };
  if (e.fields) error.fields = e.fields;
  send(res, e.status, { error }, e.status === 405 ? { allow: (e as HttpError & { allow?: string }).allow ?? '' } : {});
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) {
        reject(new HttpError(413, 'payload_too_large', 'Request body is too large.'));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idempotency_key, payload)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`);
const selectHeartbeat = db.prepare("SELECT last_seen FROM heartbeat WHERE name = 'worker'");

function isJsonContentType(ct: string | undefined): boolean {
  if (!ct) return false;
  const type = ct.split(';')[0]!.trim().toLowerCase();
  return type === 'application/json' || /^application\/[a-z0-9.+-]*\+json$/.test(type);
}

function validateInt(value: unknown, name: string, min: number, max: number, fields: FieldError[]): number | undefined {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
    return undefined;
  }
  if (!Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
    return undefined;
  }
  return value;
}

