const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;
const stopController = new AbortController();

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    stopController.abort();
  });
}

const now = () => new Date().toISOString();

