// finish, so it is not counted; the job is simply attempted again.
db.prepare(`UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ?
  WHERE status = 'running'`).run(now());

