const completeStmt = db.prepare("UPDATE jobs SET status = 'completed', progress = ?, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'");
const retryStmt = db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const failStmt = db.prepare("UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const requeueStmt = db.prepare("UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'");

function claim(): JobRow | undefined {
  return claimStmt.get(now(), Date.now()) as JobRow | undefined;
}

async function wait(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: stopController.signal });
  } catch { /* aborted */ }
}

